// Original practice prompts with direct links to related external problems.
import {additionalChallenges} from './extra-challenges.js';
import {examChallenges} from './exam-challenges.js';
import {lessonCoding} from './lesson-coding.js';
import {expansionCoding} from './expansion-coding.js';
export const challenges = [
  ...expansionCoding,
  ...lessonCoding,
  ...examChallenges,
  ...additionalChallenges,
  {id:'reverse-list',lesson:'ds-list',title:'手写：原地反转单链表',level:'入门',kind:'C/C++ 编程',prompt:'实现 reverse(Node *head)，只修改 next 指针，不申请新节点。空链表和单节点也要正确。',cases:['输入：1→2→3→NULL；输出：3→2→1→NULL','输入：NULL；输出：NULL'],hint:'维护 prev、cur 和 next；改 cur->next 前先保存后继。',solution:'Node *reverse(Node *head) {\n    Node *prev = NULL, *cur = head;\n    while (cur != NULL) {\n        Node *next = cur->next;\n        cur->next = prev;\n        prev = cur;\n        cur = next;\n    }\n    return prev;\n}',analysis:'每个节点只访问一次，时间 O(n)；只使用三个指针，额外空间 O(1)。边界是空链表和只有一个节点。',links:[['力扣 206 反转链表','https://leetcode.cn/problems/reverse-linked-list/'],['牛客 BM1 反转链表','https://www.nowcoder.com/practice/75e878df47f24fdc9dc3e400ec6058ca']]},
  {id:'binary-search',lesson:'ds-binary',title:'手写：有序数组二分查找',level:'入门',kind:'C/C++ 编程',prompt:'给定递增数组 a 和目标 x，返回任意一个匹配下标；不存在返回 -1。使用闭区间 [l,r]。',cases:['输入：[1,3,5,7]，x=5；输出：2','输入：[]，x=4；输出：-1'],hint:'保持答案可能存在于 [l,r]，使用 l+(r-l)/2 计算中点。',solution:'int search(const int *a, int n, int x) {\n    int l = 0, r = n - 1;\n    while (l <= r) {\n        int mid = l + (r - l) / 2;\n        if (a[mid] == x) return mid;\n        if (a[mid] < x) l = mid + 1;\n        else r = mid - 1;\n    }\n    return -1;\n}',analysis:'每轮将候选范围约减半，时间 O(log n)，额外空间 O(1)。重点测试空数组、首尾元素和不存在。',links:[['力扣 704 二分查找','https://leetcode.cn/problems/binary-search/']]},
  {id:'tree-level',lesson:'ds-tree',title:'手写：二叉树层序遍历',level:'入门',kind:'C/C++ 编程',prompt:'从根节点开始逐层、从左到右输出节点值。请写出队列方案，并说明怎样区分层。',cases:['根 A，左 B，右 C；输出：A / B C','空树；输出：空'],hint:'每一轮先记录当前队列长度，它就是这一层的节点数。',solution:'// 伪代码（队列接口依实现而定）\nif (!root) return;\nqueue.push(root);\nwhile (!queue.empty()) {\n    size_t count = queue.size();\n    for (size_t i=0; i<count; ++i) {\n        Node *p = queue.front(); queue.pop();\n        visit(p);\n        if (p->left) queue.push(p->left);\n        if (p->right) queue.push(p->right);\n    }\n    end_level();\n}',analysis:'每个节点入队和出队各一次，时间 O(n)。队列空间与最大层宽相关，最坏 O(n)。',links:[['力扣 102 二叉树的层序遍历','https://leetcode.cn/problems/binary-tree-level-order-traversal/']]},
  {id:'merge-lists',lesson:'ds-list',title:'手写：合并两个有序链表',level:'入门',kind:'C/C++ 编程',prompt:'两个链表均按非递减顺序排列。复用原节点，将它们连接成一个有序链表并返回头节点。',cases:['1→4 与 2→3；输出：1→2→3→4','空链表与 1→2；输出：1→2'],hint:'用哑节点保存新链表起点；每次取两个当前节点中较小的一个。',solution:'Node *merge(Node *a, Node *b) {\n    Node dummy = {0, NULL};\n    Node *tail = &dummy;\n    while (a && b) {\n        if (a->val <= b->val) { tail->next = a; a = a->next; }\n        else { tail->next = b; b = b->next; }\n        tail = tail->next;\n    }\n    tail->next = a ? a : b;\n    return dummy.next;\n}',analysis:'每个节点只处理一次，时间 O(n+m)，额外空间 O(1)。注意空链表和最后剩余链表的连接。',links:[['力扣 21 合并两个有序链表','https://leetcode.cn/problems/merge-two-sorted-lists/']]},
  {id:'ring-buffer',lesson:'ds-queue',title:'手写：固定容量环形队列',level:'进阶',kind:'嵌入式编程',prompt:'实现容量 N 的字节环形队列，采用“保留一个槽位”区分满与空，并给出 push/pop 的判定。',cases:['N=4，可用容量为 3','空：head==tail；满：(tail+1)%N==head'],hint:'写入后更新 tail；读取后更新 head。中断与任务并发访问时要另行处理同步。',solution:'bool push(Ring *r, uint8_t x) {\n    size_t next = (r->tail + 1) % N;\n    if (next == r->head) return false;\n    r->buf[r->tail] = x; r->tail = next;\n    return true;\n}\nbool pop(Ring *r, uint8_t *out) {\n    if (r->head == r->tail) return false;\n    *out = r->buf[r->head];\n    r->head = (r->head + 1) % N;\n    return true;\n}',analysis:'单次 push/pop 为 O(1)，存储空间 O(N)。题中的逻辑未涵盖中断与任务并发同步；实际工程要结合平台原子性和内存顺序设计。',links:[]},
  {id:'uart-parser',lesson:'p-uart',title:'手写：串口帧解析状态机',level:'进阶',kind:'嵌入式编程',prompt:'设计一段解析器，帧格式为 0xAA、长度 len、len 字节载荷、异或校验。要求支持半包、连帧、非法长度和超时。',cases:['输入分两次到达：AA 02 10 / 20 32；仍应解析为一个帧','输入：AA FF ...；若 FF 超出缓冲容量，应丢弃并重同步'],hint:'设计 WAIT_HEAD、WAIT_LEN、WAIT_PAYLOAD、WAIT_CHECK 四个状态。每收到 1 字节推进一次。',solution:'// 核心状态转移（省略结构体与时钟接口）\nswitch (state) {\ncase WAIT_HEAD: if (byte==0xAA) state=WAIT_LEN; break;\ncase WAIT_LEN: if (byte>MAX_PAYLOAD) reset();\n               else { len=byte; pos=0; xor_sum=byte; state=len?WAIT_PAYLOAD:WAIT_CHECK; } break;\ncase WAIT_PAYLOAD: payload[pos++]=byte; xor_sum^=byte;\n                   if (pos==len) state=WAIT_CHECK; break;\ncase WAIT_CHECK: if (byte==xor_sum) deliver(payload,len);\n                 reset(); break;\n}\n// 超时后 reset()；新帧头重同步策略按协议设计。',analysis:'解析过程对每个字节 O(1)，总时间 O(n)，缓冲空间 O(MAX_PAYLOAD)。校验失败和超时时只重置当前帧，不影响后续字节流。',links:[]},
  {id:'spiral-review',lesson:'p-spi',title:'读波形：判断 SPI 模式',level:'入门',kind:'时序推演',prompt:'已知片选低有效，SCK 在片选期间空闲高电平，主机在第二个有效边沿采样。求 CPOL、CPHA、SPI 模式和采样边沿方向。',cases:['SCK：高 → 低 → 高，第二边沿是上升沿'],hint:'先由空闲电平确定 CPOL，再由第几个边沿采样确定 CPHA。',solution:'CPOL=1，CPHA=1，模式 3；第二个有效边沿为上升沿，数据在该边沿采样。',analysis:'模式号按 CPOL/CPHA 的两位组合确定。空闲高时首边沿下降、次边沿上升；第二边沿采样意味着 CPHA=1。',links:[]},
  {id:'rtt-queue',lesson:'r-queue',title:'设计题：队列传指针时的所有权',level:'进阶',kind:'场景设计',prompt:'传感器任务把 256 字节数据块指针发给存储任务。请定义缓冲区池、发送失败、消费完成时的所有权和回收规则。',cases:['发送成功：生产者不得再改该缓冲区','发送失败：生产者仍拥有缓冲区并按策略重试或回收'],hint:'可以使用固定大小缓冲区池，将“空闲缓冲区”和“待写缓冲区”分别排队。',solution:'固定池创建若干 256 字节块。生产者取空闲块并填充；发送成功后所有权转给存储任务。存储任务完成 Flash 写入后归还空闲队列。发送失败则生产者保留块，按超时策略重试或归还。记录队列满与池耗尽次数。',analysis:'核心是任何时刻一个缓冲区只有一个可写拥有者。发送指针只复制地址，队列不会深拷贝 256 字节。需明确掉电、存储失败和任务退出后的回收策略。',links:[]},
  {id:'brackets',lesson:'ds-queue',title:'手写：有效括号检查',level:'入门',kind:'C/C++ 编程',prompt:'字符串只包含 ()[]{}。判断每个右括号是否与最近一个尚未匹配的左括号同类；空字符串视为有效。',cases:['输入：([])；输出：有效','输入：([)]；输出：无效'],hint:'左括号入栈；遇到右括号时检查栈顶，结束后栈应为空。',solution:'bool valid(const char *s) {\n    size_t n = strlen(s), top = 0;\n    char *stack = malloc(n ? n : 1);\n    if (!stack) return false;\n    for (size_t i=0; i<n; ++i) {\n        char c=s[i];\n        if (c==\'(\' || c==\'{\' || c==\'[\') { stack[top++]=c; continue; }\n        if (top==0) { free(stack); return false; }\n        char t=stack[--top];\n        if (!((t==\'(\'&&c==\')\')||(t==\'[\'&&c==\']\')||(t==\'{\'&&c==\'}\'))) { free(stack); return false; }\n    }\n    bool ok=top==0; free(stack); return ok;\n}',analysis:'每个字符进出栈至多一次，时间 O(n)，额外空间 O(n)。题目字符集限于六种括号；实际函数需要明确非法字符处理方式。',links:[['力扣 20 有效的括号','https://leetcode.cn/problems/valid-parentheses/']]},
  {id:'list-cycle',lesson:'ds-list',title:'手写：判断链表是否有环',level:'入门',kind:'C/C++ 编程',prompt:'在 O(1) 额外空间内判断单链表是否有环。不要修改链表。',cases:['1→2→3→2…；输出：有环','1→2→NULL；输出：无环'],hint:'慢指针每轮走一步，快指针每轮走两步；每次先检查快指针及其后继。',solution:'bool has_cycle(Node *head) {\n    Node *slow=head,*fast=head;\n    while (fast && fast->next) {\n        slow=slow->next;\n        fast=fast->next->next;\n        if (slow==fast) return true;\n    }\n    return false;\n}',analysis:'无环时快指针先到末尾；有环时两者最终相遇。时间 O(n)，额外空间 O(1)。',links:[['力扣 141 环形链表','https://leetcode.cn/problems/linked-list-cycle/']]},
  {id:'tree-depth',lesson:'ds-tree',title:'手写：二叉树最大深度',level:'入门',kind:'C/C++ 编程',prompt:'定义空树深度为 0。实现函数返回根到最远叶子的节点数。',cases:['根 A，左 B，B 的左 D；输出：3','空树；输出：0'],hint:'当前节点深度 = 1 + max(左子树深度,右子树深度)。',solution:'int depth(Node *root) {\n    if (!root) return 0;\n    int left=depth(root->left);\n    int right=depth(root->right);\n    return 1+(left>right?left:right);\n}',analysis:'每节点计算一次，时间 O(n)。额外空间为递归深度 O(h)，退化链表最坏 O(n)。',links:[['力扣 104 二叉树的最大深度','https://leetcode.cn/problems/maximum-depth-of-binary-tree/']]},
  {id:'insertion-sort',lesson:'ds-sort',title:'手写：稳定插入排序',level:'入门',kind:'C/C++ 编程',prompt:'原地将 int 数组按升序排序；相等元素保持原相对顺序。',cases:['输入：[5,1,4,2]；输出：[1,2,4,5]','输入：[1,1,2]；保持两个 1 的原顺序'],hint:'取出当前元素，将比它大的已排序元素右移；比较时使用 >，不用 >=。',solution:'void insertion_sort(int *a, size_t n) {\n    for (size_t i=1; i<n; ++i) {\n        int key=a[i]; size_t j=i;\n        while (j>0 && a[j-1]>key) {\n            a[j]=a[j-1]; --j;\n        }\n        a[j]=key;\n    }\n}',analysis:'最坏 O(n²)，已有序时 O(n)；额外空间 O(1)。只移动严格大于 key 的元素，因此稳定。',links:[]},
  {id:'packet-u16',lesson:'mem-endian',title:'手写：从大端报文读取 uint16_t',level:'入门',kind:'嵌入式编程',prompt:'给定至少两个字节的缓冲区，按网络大端序解析无符号 16 位整数。接口需明确缓冲区长度。',cases:['[0x12,0x34] → 0x1234','长度不足 2 → 返回失败'],hint:'先检查指针与长度，再把第一个字节左移 8 位并与第二个组合。',solution:'bool read_be16(const uint8_t *buf, size_t len, uint16_t *out) {\n    if (!buf || !out || len<2) return false;\n    *out=(uint16_t)(((uint16_t)buf[0]<<8)|buf[1]);\n    return true;\n}',analysis:'时间 O(1)，额外空间 O(1)。逐字节组装避免结构体对齐和主机端序依赖。',links:[]}
];
